const API_BASE_URL = 'http://localhost:8000';

export interface ApiResponse<T = any> {
  status: string;
  message?: string;
  [key: string]: any;
}

export interface Question {
  id: string;
  text: string;
  answer?: string;
  status: 'pending' | 'answered' | 'reviewing';
}

export interface ProcessResult {
  status: string;
  questions: string[];
  count: number;
  filename: string;
}

export interface AnswerResult {
  status: string;
  message: string;
  file_path: string;
  questions_count: number;
  answers_generated: number;
}

class ApiService {
  private async makeRequest<T>(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<T> {
    const url = `${API_BASE_URL}${endpoint}`;
    
    try {
      const response = await fetch(url, {
        ...options,
        headers: {
          ...options.headers,
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('API request failed:', error);
      throw error;
    }
  }

  // Authentication
  async login(username: string, password: string): Promise<ApiResponse> {
    const formData = new FormData();
    formData.append('username', username);
    formData.append('password', password);

    return this.makeRequest('/login', {
      method: 'POST',
      body: formData,
    });
  }

  // Document ingestion
  async ingestDocuments(files: File[]): Promise<ApiResponse> {
    const formData = new FormData();
    files.forEach(file => {
      formData.append('files', file);
    });

    return this.makeRequest('/ingest', {
      method: 'POST',
      body: formData,
    });
  }

  // RFP processing
  async processRFP(file: File): Promise<ProcessResult> {
    const formData = new FormData();
    formData.append('file', file);

    return this.makeRequest('/process-rfp', {
      method: 'POST',
      body: formData,
    });
  }

  // Answer generation
  async answerRFP(file: File): Promise<AnswerResult> {
    const formData = new FormData();
    formData.append('file', file);

    return this.makeRequest('/answer-rfp', {
      method: 'POST',
      body: formData,
    });
  }

  // File download
  getDownloadUrl(filePath: string): string {
    return `${API_BASE_URL}/download?file=${encodeURIComponent(filePath)}`;
  }

  // Health check
  async healthCheck(): Promise<boolean> {
    try {
      const response = await fetch(`${API_BASE_URL}/`);
      return response.ok;
    } catch {
      return false;
    }
  }
}

export const apiService = new ApiService();
export default apiService;
